draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // Avocado
  ctx.fillStyle = '#3e8e41';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2 * Math.PI);
  ctx.fill();

  // Pit
  ctx.fillStyle = '#786c3b';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 10, 0, 2 * Math.PI);
  ctx.fill();

  // Cutting
  ctx.lineWidth = 5;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.moveTo(W/2 - 50 + Math.sin(t) * 20, H/2);
  ctx.lineTo(W/2 + 50 + Math.sin(t) * 20, H/2);
  ctx.stroke();

  // Knife
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.moveTo(W/2 - 50 + Math.sin(t) * 20, H/2 - 20);
  ctx.lineTo(W/2 - 50 + Math.sin(t) * 20, H/2 + 20);
  ctx.stroke();

  ctx.restore();
}
